style.css:
@-moz-document domain("scratch.mit.edu") {
/* Full pink background */
html, body, .page-wrapper, .site-wrapper {
    background-color: #ffcce0 !important; /* soft pastel pink */
}

/* Remove all borders and shadows globally */
* {
    border: none !important;
    box-shadow: none !important;
    outline: none !important;
    background-image: none !important;
}

/* Navigation Bar */
header.site-header, nav.site-header {
    background-color: #ff99c1 !important; /* cute pink nav */
    border-radius: 0 !important; /* keep flat */
    box-shadow: none !important;
}

/* Nav text in pink */
header.site-header a, header.site-header span, header.site-header h1, nav.site-header a, nav.site-header span {
    color: #ff69b4 !important; /* pink text */
    font-family: 'Comic Sans MS', cursive, sans-serif !important;
}

/* Optional: subtle sparkle dots in nav */
header.site-header::after {
    content: '✨?✨';
    font-size: 14px;
    margin-left: 10px;
}
}
